-- Level 1 listening (5 Arabic questions) appended to every Level 1 midterm / final paper. Idempotent: papers that already have an @@audio question are skipped.
do $do$ declare ex record; q jsonb; qid uuid; n int; payload jsonb := $j${"midterm":[{"text":"@@sec: الاستماع: استمع إلى الصوت ثم اختر الإجابة الصحيحة\n@@audio: /listening/level1/midterm-m1.mp3\n@@opts: مِنْ سُورِيَا|مِنْ مِصْرَ|مِنْ تُرْكِيَا\nمِنْ أَيْنَ زَيْنَب؟","criteria":"مِنْ مِصْرَ"},{"text":"@@audio: /listening/level1/midterm-m2.mp3\n@@opts: طَبِيب|مُدَرِّس|مُهَنْدِس\nمَا مِهْنَةُ وَالِدِ عَلِيّ؟","criteria":"مُهَنْدِس"},{"text":"@@audio: /listening/level1/midterm-m3.mp3\n@@opts: ثَلَاثُ غُرَف|أَرْبَعُ غُرَف|خَمْسُ غُرَف\nكَمْ غُرْفَةً فِي البَيْتِ؟","criteria":"ثَلَاثُ غُرَف"},{"text":"@@audio: /listening/level1/midterm-m4.mp3\n@@opts: مُبَكِّراً|مُتَأَخِّراً|عِنْدَ الفَجْر\nمَتَى يَسْتَيْقِظُ طَارِق يَوْمَ العُطْلَة؟","criteria":"مُتَأَخِّراً"},{"text":"@@audio: /listening/level1/midterm-m5.mp3\n@@opts: أَذْهَبُ بِالحَافِلَة|أَسْتَيْقِظُ مُبَكِّراً|أَقْرَأُ القُرْآن\nاخْتَرِ الجَوَابَ المُنَاسِب.","criteria":"أَقْرَأُ القُرْآن"}],"final":[{"text":"@@sec: الاستماع: استمع إلى الصوت ثم اختر الإجابة الصحيحة\n@@audio: /listening/level1/final-f1.mp3\n@@opts: السَّمَكُ وَالأَرُزّ|الدَّجَاجُ وَالخُبْز|اللَّحْمُ وَالسَّلَطَة\nمَاذَا تَطْلُبُ المُسَافِرَةُ مِنَ الطَّعَام؟","criteria":"الدَّجَاجُ وَالخُبْز"},{"text":"@@audio: /listening/level1/final-f2.mp3\n@@opts: بِالسَّيَّارَة|بِالحَافِلَة|بِالطَّائِرَة\nكَيْفَ يُسَافِرُ صَالِح إِلَى المَدِينَة؟","criteria":"بِالطَّائِرَة"},{"text":"@@audio: /listening/level1/final-f3.mp3\n@@opts: سِتُّ حِصَص|خَمْسُ حِصَص|سَبْعُ حِصَص\nكَمْ حِصَّةً يَدْرُسُ غَسَّان فِي اليَوْم؟","criteria":"سِتُّ حِصَص"},{"text":"@@audio: /listening/level1/final-f4.mp3\n@@opts: ثَلَاثَةُ أَطْفَال|سِتَّةُ أَطْفَال|خَمْسَةُ أَطْفَال\nكَمْ طِفْلاً لِمَرْيَم؟","criteria":"خَمْسَةُ أَطْفَال"},{"text":"@@audio: /listening/level1/final-f5.mp3\n@@opts: أُصَلِّي الفَجْرَ فِي البَيْت|أُصَلِّي الظُّهْرَ فِي المَسْجِد|أَذْهَبُ بِالسَّيَّارَة\nاخْتَرِ الجَوَابَ المُنَاسِب.","criteria":"أُصَلِّي الفَجْرَ فِي البَيْت"}]}$j$::jsonb;
begin
 for ex in select id, exam_kind from public.written_exams where level=1 and exam_kind in ('midterm','final') loop
  if exists (select 1 from public.written_exam_questions where exam_id=ex.id and question_text like '%@@audio:%') then continue; end if;
  select coalesce(max(order_num),-1)+1 into n from public.written_exam_questions where exam_id=ex.id;
  for q in select value from jsonb_array_elements(payload->ex.exam_kind) loop
   insert into public.written_exam_questions(exam_id, order_num, type, question_text) values (ex.id, n, 'short_answer', q->>'text') returning id into qid;
   insert into public.written_exam_criteria(question_id, criteria_text) values (qid, q->>'criteria');
   n := n+1;
  end loop;
 end loop;
end $do$;
